```js
// Function declaration — hoisted, can be called before definition
function greet(name) {
  return `Hello, ${name}!`
}

// Arrow function — shorter, no own `this`
const double = (n) => n * 2

// Closure — inner function remembers outer scope
function makeCounter(start = 0) {
  let count = start  // enclosed variable
  return {
    increment: () => ++count,
    decrement: () => --count,
    value: () => count,
  }
}
const counter = makeCounter(10)
console.log(counter.increment()) // 11
console.log(counter.value())     // 11
```
Closures are the mechanism behind React hooks like `useState` — the state value is a closed-over variable inside the React internals.
